sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float beatTime;
uniform float beatIndex;
uniform float strength;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
half4 main(float2 xy) {
    half4 c = image.eval(xy);
    return half4(min(c.rgb * half(exp2(strength * beat)), half3(c.a)), c.a);
}
